SET NAMES utf8mb4; SET time_zone='+00:00'; CREATE TABLE IF NOT EXISTS ap_payment_schedules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,schedule_number VARCHAR(80) NOT NULL UNIQUE,company_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,scheduled_date DATE NOT NULL,discount_date DATE NULL,gross_amount DECIMAL(18,2) NOT NULL DEFAULT 0,credit_amount DECIMAL(18,2) NOT NULL DEFAULT 0,net_amount DECIMAL(18,2) NOT NULL DEFAULT 0,currency_code CHAR(3) NOT NULL DEFAULT 'USD',payment_method VARCHAR(40) NOT NULL,priority VARCHAR(20) NOT NULL DEFAULT 'normal',status VARCHAR(32) NOT NULL DEFAULT 'scheduled',hold_reason TEXT NOT NULL,owner_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_schedule_company_date (company_id,scheduled_date,status),KEY idx_ap_schedule_supplier (supplier_id,scheduled_date),KEY idx_ap_schedule_invoice (invoice_id,status),CONSTRAINT fk_ap_schedule_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_schedule_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id),CONSTRAINT fk_ap_schedule_invoice FOREIGN KEY (invoice_id) REFERENCES supplier_invoices(id),CONSTRAINT fk_ap_schedule_owner FOREIGN KEY (owner_id) REFERENCES users(id),CONSTRAINT fk_ap_schedule_reviewer FOREIGN KEY (reviewer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_payment_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_number VARCHAR(80) NOT NULL UNIQUE,company_id BIGINT UNSIGNED NOT NULL,payment_method VARCHAR(40) NOT NULL,currency_code CHAR(3) NOT NULL DEFAULT 'USD',execution_date DATE NOT NULL,bank_account_reference VARCHAR(190) NOT NULL,gross_amount DECIMAL(18,2) NOT NULL DEFAULT 0,credit_amount DECIMAL(18,2) NOT NULL DEFAULT 0,net_amount DECIMAL(18,2) NOT NULL DEFAULT 0,invoice_count INT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL DEFAULT 'draft',prepared_by BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NOT NULL,released_by BIGINT UNSIGNED NULL,batch_hash CHAR(64) NOT NULL,evidence_note TEXT NOT NULL,reviewed_at DATETIME NULL,approved_at DATETIME NULL,released_at DATETIME NULL,settled_at DATETIME NULL,locked_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_batch_company_status (company_id,status,execution_date),KEY idx_ap_batch_execution (execution_date,payment_method),CONSTRAINT fk_ap_batch_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_batch_preparer FOREIGN KEY (prepared_by) REFERENCES users(id),CONSTRAINT fk_ap_batch_reviewer FOREIGN KEY (reviewed_by) REFERENCES users(id),CONSTRAINT fk_ap_batch_approver FOREIGN KEY (approved_by) REFERENCES users(id),CONSTRAINT fk_ap_batch_releaser FOREIGN KEY (released_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_supplier_credits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,credit_number VARCHAR(80) NOT NULL UNIQUE,company_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NULL,credit_type VARCHAR(64) NOT NULL,credit_memo_number VARCHAR(120) NOT NULL,credit_date DATE NOT NULL,expiration_date DATE NULL,currency_code CHAR(3) NOT NULL DEFAULT 'USD',original_amount DECIMAL(18,2) NOT NULL DEFAULT 0,applied_amount DECIMAL(18,2) NOT NULL DEFAULT 0,remaining_amount DECIMAL(18,2) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL DEFAULT 'draft',owner_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_credit_supplier (supplier_id,status,expiration_date),KEY idx_ap_credit_company (company_id,status),CONSTRAINT fk_ap_credit_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_credit_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id),CONSTRAINT fk_ap_credit_invoice FOREIGN KEY (invoice_id) REFERENCES supplier_invoices(id),CONSTRAINT fk_ap_credit_owner FOREIGN KEY (owner_id) REFERENCES users(id),CONSTRAINT fk_ap_credit_reviewer FOREIGN KEY (reviewer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_payment_batch_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,credit_id BIGINT UNSIGNED NULL,gross_amount DECIMAL(18,2) NOT NULL DEFAULT 0,credit_amount DECIMAL(18,2) NOT NULL DEFAULT 0,net_amount DECIMAL(18,2) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL DEFAULT 'included',evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ap_batch_invoice (batch_id,invoice_id),KEY idx_ap_batch_item_invoice (invoice_id,status),KEY idx_ap_batch_item_supplier (supplier_id,batch_id),CONSTRAINT fk_ap_batch_item_batch FOREIGN KEY (batch_id) REFERENCES ap_payment_batches(id) ON DELETE CASCADE,CONSTRAINT fk_ap_batch_item_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_batch_item_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id),CONSTRAINT fk_ap_batch_item_invoice FOREIGN KEY (invoice_id) REFERENCES supplier_invoices(id),CONSTRAINT fk_ap_batch_item_credit FOREIGN KEY (credit_id) REFERENCES ap_supplier_credits(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_supplier_payment_instructions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,instruction_number VARCHAR(80) NOT NULL UNIQUE,company_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,vault_reference VARCHAR(190) NOT NULL,instruction_fingerprint CHAR(64) NOT NULL,payment_method VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending_verification',requested_by BIGINT UNSIGNED NOT NULL,verified_by BIGINT UNSIGNED NULL,requested_at DATETIME NOT NULL,verified_at DATETIME NULL,effective_date DATE NOT NULL,cooling_until DATE NOT NULL,callback_evidence TEXT NOT NULL,change_reason TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_instruction_supplier (supplier_id,company_id,status),KEY idx_ap_instruction_cooling (status,cooling_until),CONSTRAINT fk_ap_instruction_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_instruction_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id),CONSTRAINT fk_ap_instruction_requester FOREIGN KEY (requested_by) REFERENCES users(id),CONSTRAINT fk_ap_instruction_verifier FOREIGN KEY (verified_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_payment_executions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,execution_number VARCHAR(80) NOT NULL UNIQUE,batch_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,idempotency_key CHAR(64) NOT NULL UNIQUE,provider_reference VARCHAR(190) NOT NULL,settlement_reference VARCHAR(190) NOT NULL,execution_status VARCHAR(32) NOT NULL,executed_amount DECIMAL(18,2) NOT NULL DEFAULT 0,fee_amount DECIMAL(18,2) NOT NULL DEFAULT 0,failure_code VARCHAR(80) NOT NULL,failure_reason TEXT NOT NULL,transmitted_at DATETIME NULL,accepted_at DATETIME NULL,settled_at DATETIME NULL,returned_at DATETIME NULL,created_by BIGINT UNSIGNED NOT NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_execution_batch (batch_id,created_at),KEY idx_ap_execution_status (execution_status,created_at),CONSTRAINT fk_ap_execution_batch FOREIGN KEY (batch_id) REFERENCES ap_payment_batches(id) ON DELETE CASCADE,CONSTRAINT fk_ap_execution_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_execution_user FOREIGN KEY (created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_remittance_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,remittance_number VARCHAR(80) NOT NULL UNIQUE,batch_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,payment_reference VARCHAR(190) NOT NULL,settlement_reference VARCHAR(190) NOT NULL,payment_date DATE NOT NULL,gross_amount DECIMAL(18,2) NOT NULL DEFAULT 0,credit_amount DECIMAL(18,2) NOT NULL DEFAULT 0,discount_amount DECIMAL(18,2) NOT NULL DEFAULT 0,withheld_amount DECIMAL(18,2) NOT NULL DEFAULT 0,net_amount DECIMAL(18,2) NOT NULL DEFAULT 0,currency_code CHAR(3) NOT NULL DEFAULT 'USD',delivery_status VARCHAR(32) NOT NULL DEFAULT 'available',supplier_acknowledged_at DATETIME NULL,supplier_visible TINYINT(1) NOT NULL DEFAULT 1,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_remittance_supplier (supplier_id,payment_date),KEY idx_ap_remittance_batch (batch_id,supplier_id),CONSTRAINT fk_ap_remittance_batch FOREIGN KEY (batch_id) REFERENCES ap_payment_batches(id) ON DELETE CASCADE,CONSTRAINT fk_ap_remittance_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_remittance_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_reconciliations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reconciliation_number VARCHAR(80) NOT NULL UNIQUE,batch_id BIGINT UNSIGNED NOT NULL,execution_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,expected_amount DECIMAL(18,2) NOT NULL DEFAULT 0,settled_amount DECIMAL(18,2) NOT NULL DEFAULT 0,fee_amount DECIMAL(18,2) NOT NULL DEFAULT 0,currency_variance DECIMAL(18,2) NOT NULL DEFAULT 0,settlement_date DATE NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'pending',owner_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,provider_reference VARCHAR(190) NOT NULL,bank_reference VARCHAR(190) NOT NULL,evidence_note TEXT NOT NULL,reconciled_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ap_reconciliation_batch (batch_id),KEY idx_ap_reconciliation_status (company_id,status,settlement_date),CONSTRAINT fk_ap_reconciliation_batch FOREIGN KEY (batch_id) REFERENCES ap_payment_batches(id) ON DELETE CASCADE,CONSTRAINT fk_ap_reconciliation_execution FOREIGN KEY (execution_id) REFERENCES ap_payment_executions(id),CONSTRAINT fk_ap_reconciliation_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_reconciliation_owner FOREIGN KEY (owner_id) REFERENCES users(id),CONSTRAINT fk_ap_reconciliation_reviewer FOREIGN KEY (reviewer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_accounting_periods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,period_number VARCHAR(80) NOT NULL UNIQUE,company_id BIGINT UNSIGNED NOT NULL,fiscal_year INT UNSIGNED NOT NULL,period_label VARCHAR(120) NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'open',soft_closed_at DATETIME NULL,hard_closed_at DATETIME NULL,locked_at DATETIME NULL,owner_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ap_period_scope (company_id,period_start,period_end),KEY idx_ap_period_status (company_id,status,period_end),CONSTRAINT fk_ap_period_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_period_owner FOREIGN KEY (owner_id) REFERENCES users(id),CONSTRAINT fk_ap_period_reviewer FOREIGN KEY (reviewer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_accrual_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,accrual_number VARCHAR(80) NOT NULL UNIQUE,accounting_period_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,purchase_order_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,accrual_type VARCHAR(64) NOT NULL,received_value DECIMAL(18,2) NOT NULL DEFAULT 0,invoiced_value DECIMAL(18,2) NOT NULL DEFAULT 0,accrual_amount DECIMAL(18,2) NOT NULL DEFAULT 0,methodology TEXT NOT NULL,reversal_date DATE NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'draft',owner_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT UNSIGNED NOT NULL,evidence_note TEXT NOT NULL,approved_at DATETIME NULL,reversed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_accrual_period (accounting_period_id,status),KEY idx_ap_accrual_po (purchase_order_id,accounting_period_id),CONSTRAINT fk_ap_accrual_period FOREIGN KEY (accounting_period_id) REFERENCES ap_accounting_periods(id) ON DELETE CASCADE,CONSTRAINT fk_ap_accrual_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_accrual_po FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id),CONSTRAINT fk_ap_accrual_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id),CONSTRAINT fk_ap_accrual_owner FOREIGN KEY (owner_id) REFERENCES users(id),CONSTRAINT fk_ap_accrual_reviewer FOREIGN KEY (reviewer_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_close_certifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,certification_number VARCHAR(80) NOT NULL UNIQUE,accounting_period_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,certification_type VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'draft',open_invoice_count INT UNSIGNED NOT NULL DEFAULT 0,unsettled_batch_count INT UNSIGNED NOT NULL DEFAULT 0,unreconciled_count INT UNSIGNED NOT NULL DEFAULT 0,unapplied_credit_amount DECIMAL(18,2) NOT NULL DEFAULT 0,grni_amount DECIMAL(18,2) NOT NULL DEFAULT 0,prepared_by BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NOT NULL,evidence_note TEXT NOT NULL,certified_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_ap_certification_period (accounting_period_id,certification_type),CONSTRAINT fk_ap_certification_period FOREIGN KEY (accounting_period_id) REFERENCES ap_accounting_periods(id) ON DELETE CASCADE,CONSTRAINT fk_ap_certification_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_certification_preparer FOREIGN KEY (prepared_by) REFERENCES users(id),CONSTRAINT fk_ap_certification_reviewer FOREIGN KEY (reviewed_by) REFERENCES users(id),CONSTRAINT fk_ap_certification_approver FOREIGN KEY (approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; CREATE TABLE IF NOT EXISTS ap_governance_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(80) NOT NULL,from_status VARCHAR(32) NULL,to_status VARCHAR(32) NULL,severity VARCHAR(20) NOT NULL DEFAULT 'medium',amount DECIMAL(18,2) NOT NULL DEFAULT 0,evidence_note TEXT NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_ap_event_company (company_id,created_at),KEY idx_ap_event_entity (entity_type,entity_id,created_at),KEY idx_ap_event_type (event_type,created_at),CONSTRAINT fk_ap_event_company FOREIGN KEY (company_id) REFERENCES companies(id),CONSTRAINT fk_ap_event_user FOREIGN KEY (created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; INSERT IGNORE INTO permissions (permission_key,area,action,description) VALUES ('accounts_payable.view','accounts_payable','view','View accounts payable, cash forecast, settlement, reconciliation, accrual, and close governance'),('accounts_payable.create','accounts_payable','create','Create payment schedules, batches, supplier credits, periods, and accruals'),('accounts_payable.edit','accounts_payable','edit','Edit draft accounts-payable records and payment batches'),('accounts_payable.submit','accounts_payable','submit','Submit payment and close records for independent review'),('accounts_payable.review','accounts_payable','review','Review payment batches, credits, accruals, and close evidence'),('accounts_payable.approve','accounts_payable','approve','Approve payment batches and verified payment-instruction references'),('accounts_payable.execute','accounts_payable','execute','Release payment batches and record external execution evidence'),('accounts_payable.reconcile','accounts_payable','reconcile','Independently reconcile settled payments'),('accounts_payable.close','accounts_payable','close','Soft close, hard close, certify, and lock accounting periods'),('accounts_payable.export','accounts_payable','export','Export governed accounts-payable data'); INSERT IGNORE INTO role_permissions (role_id,permission_id,granted_by) SELECT r.id,p.id,NULL FROM roles r JOIN permissions p ON p.area='accounts_payable' WHERE r.code IN ('system_administrator','company_administrator'); INSERT IGNORE INTO role_permissions (role_id,permission_id,granted_by) SELECT r.id,p.id,NULL FROM roles r JOIN permissions p ON p.permission_key IN ('accounts_payable.view','accounts_payable.create','accounts_payable.edit','accounts_payable.submit','accounts_payable.review','accounts_payable.export') WHERE r.code='procurement_manager'; INSERT IGNORE INTO role_permissions (role_id,permission_id,granted_by) SELECT r.id,p.id,NULL FROM roles r JOIN permissions p ON p.permission_key IN ('accounts_payable.view','accounts_payable.approve','accounts_payable.close','accounts_payable.export') WHERE r.code='executive'; INSERT IGNORE INTO role_permissions (role_id,permission_id,granted_by) SELECT r.id,p.id,NULL FROM roles r JOIN permissions p ON p.permission_key IN ('accounts_payable.view','accounts_payable.create','accounts_payable.edit','accounts_payable.submit') WHERE r.code='data_contributor'; INSERT IGNORE INTO role_permissions (role_id,permission_id,granted_by) SELECT r.id,p.id,NULL FROM roles r JOIN permissions p ON p.permission_key IN ('accounts_payable.view','accounts_payable.review','accounts_payable.approve','accounts_payable.execute','accounts_payable.reconcile','accounts_payable.close','accounts_payable.export') WHERE r.code='reviewer'; INSERT IGNORE INTO role_permissions (role_id,permission_id,granted_by) SELECT r.id,p.id,NULL FROM roles r JOIN permissions p ON p.permission_key='accounts_payable.view' WHERE r.code='read_only'; INSERT INTO schema_migrations (version,description,checksum_sha256) VALUES ('5.2-section23','Accounts-payable schedules, payment batches and items, supplier credits, verified payment-instruction references, external execution evidence, remittances, reconciliations, accounting periods, accruals, close certifications, immutable AP events, and AP permissions',NULL) ON DUPLICATE KEY UPDATE description=VALUES(description);
